DELETE FROM seinfo_freeboard_comments
WHERE freeboard_no = #{freeboardNo}
  AND EXISTS (
      SELECT 1 FROM seinfo_freeboard_posts p
      WHERE p.freeboard_no = #{freeboardNo}
        AND (#{actorAdmin} = TRUE OR p.user_id = #{actorEmail})
  )

